// eslint-disable-next-line @typescript-eslint/no-namespace
namespace Gordic.Pok.WebClient {

    @Decorators.gcontent
    export class GPokHromadnePredaniPokTab extends GContentBase {

        pokDoklady: Gordic.Hpl.Interface.GPokDokladDto[];
        private pokKniha: Gordic.Hpl.Interface.GPokKnihaDto;
        private subrada: string;
        private faze: string;

        onContentReady() {

            var that = this;


            this.title = "Hromadné předání do POK";
            this.setBreadcrumbs([{ caption: this.title, defaultAction: true }]);

            var gf = new Gordic.Data.GridFormat();
            gf.addTextColumn({
                name: "ixp",
                caption: "jres:31302005", //RC 31302005 : PID
                sortable: false
            });

            const gridActionDetail = new GAction($.extend(true, Gordic.Eko.Action.actionDetail({
                run: function (ev, ctx) {
                    that.navigate("Gordic.Pok.WebClient.GPokDetailDokladuTab", {
                        ixp: ctx.cellInfo.data.ixp,
                        newPodani: false,
                        Id: "GPokDetailDokladu#"
                    });
                },
                enabled: true
            }), { name: "actDetail" }))


            this.navigate<Gordic.Eko.Components.TwoStepsOptions<Gordic.Hpl.Interface.GPokDokladDto>>(Gordic.Eko.Components.TwoStepsContent, {
                title: "Hromadné předání do POK",
                gridFormat: gf,
                keys: "ixp",
                data: this.pokDoklady,
                indicatorType: "KPI",
                firstStep: {
                    title: "Hromadné předání do POK",
                    description: "Kontrola a doplnění údajů pro předání dokladů do POK",
                    gridTabTitle: "Vybrané pokladní doklady",
                    defaultAction: gridActionDetail,
                    form: new Gordic.Forms.Form({ name: "formDlg2", layoutDescriptor: "L2M2S1, L-2-10-0, M-12-12-0, S-12-12-0" })
                        .addRow("Kniha")
                        .addField("gselectbox",
                            Gordic.Prefabs.Select.poksden(),
                            {
                                dropdown: true,
                                name: "ixp_den",
                                validators: [new Gordic.Validators.Required()],
                                serverFilters: {
                                    ico: that.gpc.ico,
                                    ucs: that.gpc.ucs,
                                    rok: that.gpc.rok,
                                    ixs_vpk: that.pokKniha.ixs_vpk,
                                    mena: that.pokKniha.mena
                                } 
                            })
                        .addRow("Cíl")
                        .addField("gselectbox",
                            Gordic.Prefabs.Select.ginsfun(),
                            {
                                name: "referent",
                                validators: [new Gordic.Validators.Required()],
                                serverFilters: {
                                    aktivita: 100,
                                    VrfuIxpDen: that.pokKniha.ixp_den,
                                    VrfuTypAg: "pok",
                                    DlePovolenychFazi: that.faze,
                                    VrfuAktivita: 100,
                                    VrfuSubrada: that.subrada
                                }
                            })
                    
                    ,
                    checkAction: (model, data) => {


                        var view = new Gordic.Data.View(data, { key: "ixp" });
                        var ixpArray = data.map(function (d) { return d.ixp; });
                        let i = 0;

                        let def = $.Deferred();

                        ixpArray.forEach(function (x) {

                            that.isl.PokDoklad.seznamPermissions(rq => { return { ixp: x } }).get()
                                .done(function (data) {

                                    view.getDataRows(true).forEach(function (meta) {



                                        if (meta.data.ixp === x) {


                                            i = i + 1;

                                            meta.data.wiz_kind = data.LzePredatDoPok.value ? Gordic.Isl.GOperationResultKind.Success : Gordic.Isl.GOperationResultKind.Error;
                                            meta.data.wiz_txt_err = data.LzePredatDoPok.message;
                                            meta.data.wiz_check = data.LzePredatDoPok.value;
                                        }

                                        if (i == ixpArray.length) {
                                            def.resolve(view)
                                        }
                                    });

                                })
                                .fail(function (xhr, type, vobj) {

                                    view.getDataRows(true).forEach(function (meta) {
                                        vobj.handled = true;
                                        if (meta.data.ixp === x) {
                                            i = i + 1;
                                            meta.data.wiz_kind = Gordic.Isl.GOperationResultKind.Error;
                                            meta.data.wiz_txt_err = vobj.baseMessage;
                                            meta.data.wiz_check = false;
                                        }

                                        if (i == ixpArray.length) {
                                            def.resolve(view)
                                        }
                                    });


                                });
                        })
                        return def.promise();
                    },
                    nextActionName: "Předat",
                    nextAction: (model, data) => {

                        let def = $.Deferred();
                        let y = 0;

                        if (data.length == 0)
                            def.resolve(data);


                        data.forEach(function (row) {
                            that.isl.PokDoklad.predatDoPok(
                                rq => {
                                    return {
                                        ixp: row.ixp,                                      
                                        ixsFunPrijemce: model.referent.ixs_fun_akt,
                                        ixsSuPrijemce: model.referent.ixs_su,
                                        ixpDen: model.ixp_den.ixp_den,
                                        dotaz: true

                                    }
                                })
                                .get()
                                .done(function () {
                                    row.wiz_kind = Gordic.Isl.GOperationResultKind.Success;
                                    row.wiz_txt_err = "Doklad byl úspěšně předán!";
                                })
                                .fail(function (xhr, type, vobj) {
                                    if (type === "exception") {
                                        if (vobj.baseType === "Gordic.General.GHplValidationException") {
                                            vobj.handled = true;
                                            row.wiz_kind = Gordic.Isl.GOperationResultKind.Error;
                                            row.wiz_txt_err = vobj.baseMessage;

                                        }                                    
                                    else if (vobj.data.member == "dotaz") {
                                        //question
                                        vobj.handled = true;
                                        row.wiz_kind = Gordic.Isl.GOperationResultKind.Warning;
                                        row.wiz_txt_err = vobj.baseMessage;

                                    }
                                        else {
                                            vobj.handled = true;
                                            row.wiz_kind = Gordic.Isl.GOperationResultKind.Error;
                                            row.wiz_txt_err = vobj.baseMessage;

                                        }
                                    }
                                })
                                .always(function () {
                                    y = y + 1;

                                    if (y == data.length) {
                                        def.resolve(data)
                                    }
                                });

                        });

                        return def.promise();

                    },
                },
                lastStep:
                {
                    title: "Výsledek",
                    gridTabTitle: "Seznam předaných dokladů do POK",
                    description: "Výsledek hromadného předání dokladů do POK"
                },
                completeDelegate: (view) => {

                    that.close(true);
                },
                cancelDelegate: () => {
                    that.close(false);
                },
            }, { title: "Hromadné předání do POK" });

        }








    }


}


